const input = items[0].json || {};
const subject = String(input.subject || input.title || '').trim();
const startDateTime = String(input.startDateTime || '').trim();
const endDateTime = String(input.endDateTime || '').trim();
const timeZone = input.timeZone || 'Europe/Berlin';
const attendees = Array.isArray(input.attendees) ? input.attendees : (input.attendeeEmail ? [{ emailAddress: { address: input.attendeeEmail, name: input.attendeeName || input.attendeeEmail }, type: 'required' }] : []);
const requestBody = JSON.stringify({ subject, body: { contentType: 'Text', content: input.body || '' }, start: { dateTime: startDateTime, timeZone }, end: { dateTime: endDateTime, timeZone }, location: { displayName: input.location || '' }, attendees });
return [{ json: { ...input, subject, startDateTime, endDateTime, timeZone, attendees, requestBody, graphUrl: 'https://graph.microsoft.com/v1.0/me/events' } }];

function cleanError(value) {
  if (!value) return 'Unknown error';
  if (typeof value === 'string') return value.slice(0, 600);
  if (value.message) return String(value.message).slice(0, 600);
  return JSON.stringify(value).slice(0, 600);
}
function safeText(value) {
  return String(value ?? '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}
function person(mailbox) {
  const e = mailbox?.emailAddress || mailbox || {};
  return { name: e.name || '', email: e.address || '' };
}
function pass(response, extra = {}) {
  return [{ json: { ...extra, response, verificationStatus: 'Passed' } }];
}
function fail(tool, error, action='No Microsoft 365 state was changed.') {
  const msg = cleanError(error);
  return [{ json: { response: `Tool failed: Yes\nTool used: ${tool}\nError message: ${msg}\nAction taken: ${action}\nVerification status: Failed`, toolFailed: true, toolUsed: tool, errorMessage: msg, actionTaken: action, verificationStatus: 'Failed' } }];
}

const input = $('Prepare Graph Request').item.json;
const e = items[0].json || {};
if (e.error || !e.id) return fail('WF_CREATE_CALENDAR_EVENT', e.error || e.message || 'Calendar event was not created');
return pass(`Calendar event created: Yes\nTitle: ${e.subject || input.subject}\nDate/time: ${e.start?.dateTime || input.startDateTime} - ${e.end?.dateTime || input.endDateTime}\nAttendees: ${(input.attendees || []).map(a=>a.emailAddress?.address).filter(Boolean).join(', ') || 'None'}\nLocation: ${e.location?.displayName || input.location || ''}\nLink: ${e.webLink || ''}\nVerification status: Passed`, { event_id: e.id, webLink: e.webLink || '', timeZone: input.timeZone });
